  council: [['f', 'proof_decided'], ['f', 'proof_council'], ['choice', 'proof', 'council'], ['take', 'q_proof', 1], ['god', 'torn', 10], ['god', 'kharn', 5], ['god', 'ori', -8], ['god', 'lyara', -3]],
  collegium: [['f', 'proof_decided'], ['f', 'proof_collegium'], ['choice', 'proof', 'collegium'], ['take', 'q_proof', 1], ['god', 'ori', 8], ['god', 'seyr', 6], ['god', 'torn', 2], ['god', 'kharn', -3]],
  remembering: [['f', 'proof_decided'], ['f', 'proof_remembering'], ['choice', 'proof', 'remembering'], ['take', 'q_proof', 1], ['god', 'ori', 12], ['god', 'lyara', 6], ['god', 'torn', -6], ['god', 'issa', -4]],
  burn: [['f', 'proof_decided'], ['f', 'proof_burn'], ['f', 'abbot_gone'], ['choice', 'proof', 'burn'], ['take', 'q_proof', 1], ['god', 'ori', -14], ['god', 'issa', 8], ['god', 'kharn', 3], ['god', 'torn', -8], ['god', 'mara', 4]],
